import { createAPIFileRoute } from '@tanstack/react-start/api'
import bcrypt from 'bcryptjs'
import db, { createSession } from '../../db'

export const APIRoute = createAPIFileRoute('/api/login')({
  POST: async ({ request }) => {
    try {
      const body = await request.json()
      const { email, password } = body
      if (typeof email !== 'string' || typeof password !== 'string') {
        return new Response(JSON.stringify({ error: 'Invalid input' }), { status: 400 })
      }

      const user = db.prepare('SELECT * FROM users WHERE email = ?').get(email) as any
      if (!user) {
        return new Response(JSON.stringify({ error: 'Invalid credentials' }), { status: 401 })
      }

      const passwordMatch = bcrypt.compareSync(password, user.password_hash)
      if (!passwordMatch) {
        return new Response(JSON.stringify({ error: 'Invalid credentials' }), { status: 401 })
      }

      const { token, expiresAt } = createSession(user.id)
      const headers = new Headers()
      headers.append(
        'Set-Cookie',
        `rbac_session=${token}; HttpOnly; SameSite=Lax; Path=/; Expires=${expiresAt.toUTCString()}`
      )

      return Response.json({ user: { email: user.email, role: user.role } }, { headers })
    } catch (err) {
      return new Response(JSON.stringify({ error: 'Internal Server Error' }), { status: 500 })
    }
  },
})

import db, { getSession } from '../db'

export function getSessionFromRequest(request: Request) {
  const cookieHeader = request.headers.get('cookie')
  if (!cookieHeader) return null
  const cookies = cookieHeader.split(';').reduce((acc, cookie) => {
    const [key, ...value] = cookie.trim().split('=')
    if (key) {
      acc[key] = value.join('=')
    }
    return acc
  }, {} as Record<string, string>)
  const token = cookies['rbac_session']
  if (!token) return null
  return getSession(token)
}

import { createAPIFileRoute } from '@tanstack/react-start/api'
import { deleteSession } from '../../db'

export const APIRoute = createAPIFileRoute('/api/logout')({
  POST: async ({ request }) => {
    const cookieHeader = request.headers.get('cookie')
    let token = ''
    if (cookieHeader) {
      const cookies = cookieHeader.split(';').reduce((acc, cookie) => {
        const [key, ...value] = cookie.trim().split('=')
        if (key) {
          acc[key] = value.join('=')
        }
        return acc
      }, {} as Record<string, string>)
      token = cookies['rbac_session'] || ''
    }

    if (token) {
      deleteSession(token)
    }

    const headers = new Headers()
    headers.append(
      'Set-Cookie',
      'rbac_session=; HttpOnly; SameSite=Lax; Path=/; Expires=Thu, 01 Jan 1970 00:00:00 GMT'
    )

    return Response.json({ ok: true }, { headers })
  },
})

