                  {u.email} {u.email === user?.email && <span style={{ fontSize: '0.75rem', color: '#2563eb', backgroundColor: '#dbeafe', padding: '0.125rem 0.375rem', borderRadius: '9999px', marginLeft: '0.5rem' }}>You</span>}
                </td>
